'use strict';
const SNAPSHOT=new Date('2026-11-20T18:00:00Z');
const names=['Alex Morgan','Jordan Ellis','Casey Bennett','Taylor Reed','Sam Parker','Jamie Clarke','Morgan Hayes','Riley Brooks','Drew Carter','Avery Foster','Robin Blake','Cameron Wells','Charlie Lane','Quinn Harper','Reese Collins','Skyler James','Dakota Mills','Finley Ross','Emerson Shaw','Harper Dean','Peyton Nash','Rowan Bell','Logan Avery','Sage Martin','Elliot Grant','Hayden Cole','Blair Quinn','Kendall Price','Shawn Bailey','Devon Moore','Lee Spencer','Noel Cooper','Marley Scott','Terry Wade','Reagan Stone','Arden Miles'];
const companies=['Northstar Components','Harbor Retail Group','Cedar Health Network','Meridian Financial','Solara Energy','Evergreen Manufacturing','Juniper Stores','Silverline Care','Summit Financial Group','Helios Utilities','Atlas Materials','Bloom Retail','Crestwell Hospitals','Riverstone Payments','Windmere Energy','Oakline Industries','Vista Commerce','Meadow Health','Pinnacle Finance','Brightfield Power'];
const segments=['Industry','Retail','Healthcare','Financial services','Energy'];
const roles=['Director of Technology','Head of Data & Analytics','Strategy & Transformation Manager','Commercial Intelligence Manager','Head of Operations','IT Infrastructure Manager'];
const hypotheses=['AI governance','Data intelligence','Project prioritization','Process automation','Operational analytics','Cloud scalability'];
const descriptions=['Potential relevance to centralized AI access, usage visibility and governance. This is a role-based hypothesis, not an identified project.','Potential relevance to business-user access to data and consolidated reporting. No customer need has been confirmed.','Potential relevance to comparing strategic initiatives and allocating resources. Budget and project priorities are not known.','Potential relevance to reducing manual process steps and connecting information. No specific pain point has been confirmed.','Potential relevance to performance indicators and operational decision support. Current tooling and requirements are unknown.','Potential relevance to infrastructure reliability and scaling technology services. No infrastructure gap has been established.'];
const channels=['LinkedIn','Email','WhatsApp'];const key='igor-commercial-demo-v1';
const day=(offset)=>new Date(+SNAPSHOT-offset*86400000).toISOString();
function seed(){return names.map((name,i)=>{const s=i%5,r=i%6;const start=7+(i*11)%78;let status=i%9===0?'Meeting booked':i%7===0?'Interested':i%8===0?'Not interested':i%11===0?'Nurture':'In cadence';const events=[];let count=1+i%3;for(let n=0;n<count;n++)events.push({type:'outreach',channel:channels[(i+n)%3],date:day(Math.max(0,start-n*3)),text:['Connection introduction','Personalized solution introduction','Follow-up conversation'][n]});if(status!=='In cadence')events.push({type:'reply',channel:events.at(-1).channel,date:day(Math.max(0,start-(count-1)*3-1)),text:status==='Not interested'?'No current interest; outreach paused.':status==='Nurture'?'Timing is not right; revisit later.':'Interested in learning more; outreach paused.'});if(status==='Meeting booked')events.push({type:'meeting',channel:events.at(-1).channel,date:day(Math.max(0,start-(count-1)*3-2)),text:'Discovery meeting booked.'});return{id:i+1,name,company:companies[i%20],segment:segments[s],role:roles[r],seniority:r===0?'Director':'Head / Manager',driver:hypotheses[r],summary:descriptions[r],status,paused:status!=='In cadence',events,task:status==='Meeting booked'?'Prepare discovery agenda':status==='Interested'?'Confirm priorities and propose a discovery call':status==='Nurture'?'Review timing in 30 days':status==='Not interested'?'No further outreach planned':'Review next touch and personalize message'};});}
let guideState=null;let leads;try{const cached=JSON.parse(localStorage.getItem(key));leads=Array.isArray(cached)&&cached.length===36?cached:seed();}catch{leads=seed();}
const $=s=>document.querySelector(s);let activeLead=null,currentTab='overview';
const escape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=d=>new Intl.DateTimeFormat('en-GB',{day:'numeric',month:'short',timeZone:'UTC'}).format(new Date(d));
function save(){if(guideState)return;try{localStorage.setItem(key,JSON.stringify(leads));}catch{}}
function filters(){return{period:$('#period').value,channel:$('#channel').value,segment:$('#segment').value};}
function matchEvent(e,f){const age=(+SNAPSHOT-new Date(e.date))/86400000;return(f.channel==='all'||e.channel===f.channel)&&(f.period==='all'||age<=Number(f.period));}
function filtered(){const f=filters();return leads.filter(l=>(f.segment==='all'||l.segment===f.segment)&&l.events.some(e=>e.type==='outreach'&&matchEvent(e,f)));}
function events(){const f=filters();return filtered().flatMap(l=>l.events.filter(e=>matchEvent(e,f)).map(e=>({...e,lead:l})));}
function statusClass(s){return s.toLowerCase().replaceAll(' ','-');}
function render(){const list=filtered(),ev=events(),f=filters();const outreach=ev.filter(e=>e.type==='outreach');const replies=list.filter(l=>l.events.some(e=>e.type==='reply'&&matchEvent(e,f))).length;const meetings=list.filter(l=>l.events.some(e=>e.type==='meeting'&&matchEvent(e,f))).length;const metric=[['Contacts reached',list.length,'Unique contacts with outreach'],['Outreach activities',outreach.length,'All selected outreach events'],['Contacts replied',replies,list.length?`${Math.round(replies/list.length*100)}% of reached contacts`:'No reached contacts'],['Meetings booked',meetings,'Unique contacts, not event count']];$('#metrics').innerHTML=metric.map(([title,num,note])=>`<article class="metric"><span>${title}</span><strong>${num}</strong><small>${note}</small></article>`).join('');const vals=channels.map(c=>outreach.filter(e=>e.channel===c).length);$('#channel-chart').innerHTML=channels.map((c,i)=>bar(c,vals[i],Math.max(1,...vals))).join('');$('#funnel').innerHTML=[['Reached',list.length],['Replied',replies],['Meeting booked',meetings]].map(([s,n])=>bar(s,n,Math.max(1,list.length))).join('');const recent=[...ev].sort((a,b)=>b.date.localeCompare(a.date)).slice(0,5);$('#recent').innerHTML=recent.length?recent.map(e=>`<div class="activity"><span class="activity-icon">${e.type==='meeting'?'▦':e.type==='reply'?'≋':'◎'}</span><div><strong>${escape(e.lead.name)} · ${escape(e.lead.company)}</strong><p>${escape(e.text)} · ${escape(e.channel)}</p></div><time>${fmt(e.date)}</time></div>`).join(''):'<div class="empty">No activity matches these filters.</div>';renderRows();}
function bar(label,n,max){return`<div class="bar-row"><div class="bar-label"><span>${escape(label)}</span><strong>${n}</strong></div><div class="bar-track" role="img" aria-label="${escape(label)}: ${n}"><div class="bar-fill" style="width:${n/max*100}%"></div></div></div>`;}
function renderRows(){const query=$('#search').value.trim().toLowerCase(),status=$('#status').value;const rows=filtered().filter(l=>(status==='all'||l.status===status)&&`${l.name} ${l.company} ${l.role}`.toLowerCase().includes(query));$('#lead-rows').innerHTML=rows.length?rows.map(l=>`<tr><td><strong>${escape(l.name)}</strong><small>${escape(l.company)} · ${escape(l.segment)}</small></td><td>${escape(l.role)}</td><td>${escape(l.driver)}</td><td><span class="badge ${statusClass(l.status)}">${l.status}</span></td><td><button data-lead="${l.id}" aria-label="Open ${escape(l.name)}">View details</button></td></tr>`).join(''):'<tr><td colspan="5" class="empty">No leads match these filters. Try a different search or segment.</td></tr>';$('#lead-count').textContent=`${rows.length} fictional contacts shown`;} 
function tab(name){currentTab=name;document.querySelectorAll('[data-tab]').forEach(b=>b.setAttribute('aria-selected',String(b.dataset.tab===name)));for(const t of ['overview','prospects','cadences'])$('#view-'+t).hidden=t!==name;$('#view-title').textContent={overview:'Performance overview',prospects:'Lead explorer',cadences:'Cadence studio'}[name];$('#view-description').textContent={overview:'One view of outreach, engagement and next steps.',prospects:'A qualification hypothesis, contact history and next action.',cadences:'A consistent process that stops and adapts after a reply.'}[name];}
function message(l){return`Hi ${l.name.split(' ')[0]},\n\nI noticed your work as ${l.role.toLowerCase()} at ${l.company}. I’d welcome a conversation about how your team approaches ${l.driver.toLowerCase()}.\n\nI can share a relevant example and learn whether this is a priority for your team. Would a short discovery conversation be useful?\n\nBest,\nIgor`;} 
function openLead(id){activeLead=Number(id);detail();$('#lead-dialog').showModal();}
function detail(){const l=leads.find(l=>l.id===activeLead);if(!l)return;$('#lead-detail').innerHTML=`<div class="detail-header"><span class="detail-eyebrow">FICTIONAL CONTACT · QUALIFICATION RECORD</span><h2 id="dialog-name">${escape(l.name)}</h2><p>${escape(l.role)} · ${escape(l.company)}</p><span class="badge ${statusClass(l.status)}">${l.status}</span></div><div class="detail-meta"><span class="chip">${l.seniority}</span><span class="chip">${l.segment}</span><span class="chip">Cadence ${l.paused?'paused':'active'}</span></div><section class="detail-block"><h3>Qualification & driver</h3><p class="hypothesis"><strong>${escape(l.driver)}</strong><br>${escape(l.summary)}</p><p>Qualification source: synthetic role profile for this demonstration. No real customer research or personal data.</p></section><section class="detail-block"><h3>Conversation history</h3><ol class="timeline">${[...l.events].sort((a,b)=>a.date.localeCompare(b.date)).map(e=>`<li><time>${fmt(e.date)} · ${e.channel}</time>${escape(e.text)}</li>`).join('')}</ol></section><section class="detail-block"><h3>Personalized message preview</h3><div class="message">${escape(message(l))}</div><p class="footnote">Illustrative draft only. These controls never send a message or create a real meeting.</p><div class="demo-actions"><button class="secondary" data-action="outreach" ${l.paused?'disabled':''}>Log demo outreach</button><button class="primary" data-action="reply" ${l.status==='Interested'||l.status==='Meeting booked'?'disabled':''}>Simulate interested reply</button><button class="secondary" data-action="meeting" ${l.status!=='Interested'?'disabled':''}>Simulate meeting booked</button></div></section><section class="detail-block"><h3>Next task</h3><div class="next-task">${escape(l.task)}</div><p class="footnote">Reply handling pauses later touches. Follow-up is then managed as a human-owned task.</p></section>`;}
function notify(text){$('#notice').textContent=text;}
function action(kind){const l=leads.find(l=>l.id===activeLead);if(!l)return;const ch=$('#channel').value==='all'?'LinkedIn':$('#channel').value;const date=SNAPSHOT.toISOString();if(kind==='outreach'&&!l.paused){l.events.push({type:'outreach',channel:ch,date,text:'Demo outreach logged (nothing sent).'});notify('Demo activity logged. The contact reach count stays unique; the activity count increases.');}else if(kind==='reply'&&!['Interested','Meeting booked'].includes(l.status)){l.events.push({type:'reply',channel:ch,date,text:'Interested reply simulated; cadence paused.'});l.status='Interested';l.paused=true;l.task='Confirm priorities and propose a discovery call';notify('Interested reply recorded. Cadence paused automatically and a follow-up task created.');}else if(kind==='meeting'&&l.status==='Interested'){l.events.push({type:'meeting',channel:ch,date,text:'Discovery meeting simulated (no calendar invitation sent).'});l.status='Meeting booked';l.task='Prepare discovery agenda and validate the business priorities';notify('Demo meeting recorded. The pipeline and meeting KPI have been updated.');}save();render();detail();}
document.querySelectorAll('[data-tab]').forEach(b=>b.addEventListener('click',()=>tab(b.dataset.tab)));
document.querySelector('.workspace [role=tablist]').addEventListener('keydown',e=>{if(!['ArrowLeft','ArrowRight','Home','End'].includes(e.key))return;e.preventDefault();const buttons=[...document.querySelectorAll('[data-tab]')],i=buttons.findIndex(b=>b.dataset.tab===currentTab),n=e.key==='Home'?0:e.key==='End'?2:(i+(e.key==='ArrowRight'?1:2))%3;tab(buttons[n].dataset.tab);buttons[n].focus();});
for(const s of ['#period','#channel','#segment'])$(s).addEventListener('change',()=>{notify('');render();});$('#search').addEventListener('input',renderRows);$('#status').addEventListener('change',renderRows);$('#lead-rows').addEventListener('click',e=>{const b=e.target.closest('[data-lead]');if(b)openLead(b.dataset.lead);});$('#close-dialog').addEventListener('click',()=>$('#lead-dialog').close());$('#lead-dialog').addEventListener('click',e=>{if(e.target===$('#lead-dialog'))$('#lead-dialog').close();const b=e.target.closest('[data-action]');if(b)action(b.dataset.action);});
function legacyExample(){for(const id of ['period','channel','segment'])$('#'+id).value=id==='period'?'90':'all';$('#search').value='';$('#status').value='all';tab('prospects');render();const l=leads.find(l=>l.status==='In cadence');if(l){openLead(l.id);notify('Try “Log demo outreach”, then “Simulate interested reply”. Notice how the cadence pauses and the next task changes.');}else notify('All contacts have been updated. Reset the demo to restart the guided example.');}
$('#tour').addEventListener('click',example);$('#open-example').addEventListener('click',example);$('#reset').addEventListener('click',()=>{leads=seed();save();$('#search').value='';$('#status').value='all';for(const id of ['period','channel','segment'])$('#'+id).value=id==='period'?'90':'all';render();notify('Demo restored to its original fictional data.');});render();

// Isolated scenario: never overwrites the visitor's exploration or storage.

const guideSteps=[['Qualify before reaching out','Review the contact’s responsibility, seniority and driver hypothesis. A plausible use case is not a confirmed customer need.'],['Start a relevant conversation','The draft connects the person’s role to a business topic. It invites discovery rather than assuming an existing project.'],['Record an interested reply','The reply pauses the cadence. The next action becomes confirming priorities and arranging discovery.'],['Advance to a meeting','The fictional meeting updates the contact status and creates a preparation task. Technical alignment and proposal development come after discovery.'],['Read the impact correctly','The scenario added one outreach activity for an already-reached contact. Unique reach stays the same; replies and meetings each increase by one.']];
function showGuide(){const g=guideState,i=g.step;$('#guide-label').textContent='STEP '+(i+1)+' OF 5 · ISOLATED DEMO';$('#guide-title').textContent=guideSteps[i][0];$('#guide-copy').textContent=guideSteps[i][1];$('#guide-next').textContent=i===4?'Finish walkthrough':'Continue';}
function example(){if(guideState)endGuide();const old=JSON.parse(JSON.stringify(leads));const f={period:$('#period').value,channel:$('#channel').value,segment:$('#segment').value};leads=seed();const l=leads.find(x=>x.status==='In cadence');guideState={step:0,old,filters:f,id:l.id};['period','channel','segment'].forEach(id=>$('#'+id).value=id==='period'?'all':'all');$('#search').value='';$('#status').value='all';$('#guide').hidden=false;tab('prospects');render();showGuide();openLead(l.id);}
function endGuide(){if(!guideState)return;leads=guideState.old;for(const [id,value]of Object.entries(guideState.filters))$('#'+id).value=value;guideState=null;$('#guide').hidden=true;$('#lead-dialog').close();render();notify('Walkthrough finished. Your previous demo exploration has been restored.');}
$('#guide-next').addEventListener('click',()=>{if(!guideState)return;const g=guideState,l=leads.find(x=>x.id===g.id);if(g.step===4){endGuide();return;}g.step++;if(g.step===1)l.events.push({type:'outreach',channel:'LinkedIn',date:SNAPSHOT.toISOString(),text:'Guided example: personalized outreach recorded (nothing sent).'});if(g.step===2){l.status='Interested';l.paused=true;l.task='Confirm business priorities and arrange a discovery conversation';l.events.push({type:'reply',channel:'LinkedIn',date:SNAPSHOT.toISOString(),text:'Guided example: interested reply; cadence paused.'});}if(g.step===3){l.status='Meeting booked';l.task='Prepare discovery questions and align with the technical team';l.events.push({type:'meeting',channel:'LinkedIn',date:SNAPSHOT.toISOString(),text:'Guided example: discovery meeting booked (no invitation sent).'});}render();showGuide();if(g.step<4){openLead(g.id);}else tab('overview');});
$('#guide-exit').addEventListener('click',endGuide);
// Closing a contact reveals the next guided step without forcing timed navigation.
const baseDetail=detail;
detail=function(){baseDetail();if(guideState){const box=document.createElement('section');box.className='guide-dialog';box.innerHTML='<p class="eyebrow">STEP '+(guideState.step+1)+' OF 5</p><h3>'+guideSteps[guideState.step][0]+'</h3><p>'+guideSteps[guideState.step][1]+'</p><button class="primary" id="guide-dialog-next">Continue walkthrough</button><button class="secondary" id="guide-dialog-exit">Exit walkthrough</button>';$('#lead-detail').prepend(box);$('#guide-dialog-next').onclick=()=>{$('#lead-dialog').close();$('#guide-next').click()};$('#guide-dialog-exit').onclick=endGuide;$('#lead-dialog').querySelectorAll('[data-action]').forEach(b=>b.disabled=true);}};
